/*
 * This file was generated by the Gradle 'init' task.
 */
plugins {
    id("buildlogic.kotlin-common-conventions")
    id("buildlogic.coverage-conventions")
    id("org.jetbrains.dokka")
}

dependencies {
    // GeneratedParametersTest is meta-annotated with TestTemplate and ExtendWith, so consumers
    // compile against jupiter-api. They do not compile against the engine or against params.
    api(libs.junit.jupiter.api)
    api(project(":validation"))
    implementation(libs.junit.jupiter.params)
    implementation(kotlin("reflect"))
    implementation(kotlin("stdlib"))
    testRuntimeOnly(libs.junit.jupiter.engine)
    testRuntimeOnly(libs.junit.platform.launcher)
    testImplementation(libs.junit.platform.testkit)
    testImplementation("org.mockito:mockito-core:5.24.0")
    testImplementation("org.mockito:mockito-junit-jupiter:5.24.0")
    testImplementation("io.mockk:mockk:1.14.12")
    testImplementation("org.assertj:assertj-core:3.27.7")
    testImplementation("com.willowtreeapps.assertk:assertk:0.28.1")
}

dokka {
    dokkaSourceSets {
        main {
            samples.from(
                "$rootDir/examples/src/main/kotlin/examples/Examples.kt",
                "$rootDir/examples/src/main/kotlin/examples/CombinationExamples.kt"
            )
        }
    }
}

tasks.test {
    // Every test class in this module ends in Test. Restricting discovery to that keeps Gradle from
    // also running the EngineTestKit fixtures directly - they are nested classes with test methods,
    // and some of them fail on purpose.
    include("**/*Test.class")
}

tasks.jacocoTestCoverageVerification {
    violationRules {
        // Coverage when the gate was added, rounded down to the percent. Raising it: DEVELOPERS.md.
        rule {
            element = "BUNDLE"
            limit {
                counter = "LINE"
                value = "COVEREDRATIO"
                minimum = "0.98".toBigDecimal()
            }
            limit {
                counter = "BRANCH"
                value = "COVEREDRATIO"
                minimum = "0.92".toBigDecimal()
            }
        }
    }
}
